// Code-node "Domeinen": wat het Apps Script meestuurde. Zonder domein zoeken we eerst op de bedrijfsnaam.
const body = $('Logo gevraagd').first().json.body ?? {};
if (!/^\d{4}:[a-z0-9-]+$/.test(String(body.key ?? ""))) throw new Error("Geen geldige sleutel ontvangen.");
const domains = (Array.isArray(body.domains) ? body.domains : [])
  .map((d) => String(d).trim().toLowerCase())
  .filter((d) => /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(d))
  .slice(0, 3);
return [
  {
    json: {
      key: String(body.key),
      company: String(body.company ?? ""),
      name: String(body.name ?? body.company ?? ""),
      city: String(body.city ?? ""),
      tier: String(body.tier ?? ""),
      domains,
      needSearch: domains.length === 0
    }
  }
];

// Code-node "Zoekresultaat": Brandfetch Search gaf merken bij de naam. Hou er drie over; Claude kiest straks.
const req = $('Domeinen').first().json;
const norm = (s) =>
  String(s ?? "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/\b(b\.?\s?v\.?|n\.?\s?v\.?|holding)\b/g, "")
    .replace(/[^a-z0-9]/g, "");
const want = norm(req.company);
const hits = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r && typeof r.domain === "string" && r.domain);
// Zelfde naam eerst, dan merken die hun gegevens bij Brandfetch zelf beheren, dan een .nl-domein.
const score = (r) => (norm(r.name) === want ? 4 : norm(r.name).includes(want) || want.includes(norm(r.name)) ? 2 : 0) + (r.claimed ? 1 : 0) + (r.domain.endsWith(".nl") ? 1 : 0);
hits.sort((a, b) => score(b) - score(a));
return [{ json: { ...req, domains: [...new Set(hits.map((h) => h.domain))].slice(0, 3) } }];

// Code-node "Per domein": één item per domein voor Brandfetch. Geen domein: één leeg item, dan meldt de
// workflow netjes "niets gevonden" terug in plaats van stil te stoppen.
const req = $input.first().json;
const domains = req.domains.length ? req.domains : [""];
return domains.map((domain) => ({ json: { ...req, domain } }));

// Code-node "Kandidaten": de logo's van Brandfetch (of Logo.dev als terugval) en de vraag aan Claude.
const cfg = $('Instellingen').first().json;
const asked = $('Per domein').all().map((i) => i.json);
const req = asked[0];
const RANK = { logo: 0, symbol: 1, icon: 2 };
// Claude kan geen SVG zien; die gaat wel naar de muur (scherp op elke maat).
const VIEWABLE = ["png", "jpeg", "webp"];

const candidates = [];
$input.all().forEach((item, i) => {
  const brand = item.json ?? {};
  const domain = brand.domain ?? asked[i]?.domain ?? "";
  for (const logo of brand.logos ?? []) {
    const formats = logo.formats ?? [];
    const view = formats.find((f) => VIEWABLE.includes(f.format) && /^https:\/\//.test(f.src ?? ""));
    if (!view) continue;
    const svg = formats.find((f) => f.format === "svg" && /^https:\/\//.test(f.src ?? ""));
    candidates.push({ source: "brandfetch", domain, brand: brand.name ?? "", type: logo.type ?? "logo", theme: logo.theme ?? "", viewUrl: view.src, wallUrl: (svg ?? view).src });
  }
});
candidates.sort((a, b) => (RANK[a.type] ?? 3) - (RANK[b.type] ?? 3));

if (!candidates.length && cfg.logoDevToken) {
  for (const { domain } of asked.filter((a) => a.domain)) {
    const url = `https://img.logo.dev/${domain}?token=${cfg.logoDevToken}&size=300&format=png&retina=true`;
    candidates.push({ source: "logo.dev", domain, brand: "", type: "icon", theme: "", viewUrl: url, wallUrl: url });
  }
}

const shown = candidates.slice(0, 4);
const intro = [
  "Je helpt Oma Coby's Oliebollen met de wall of fame: een muur vol lijsten met de logo's van bedrijven die oliebollen bestelden voor dansmiddagen voor ouderen.",
  `Bedrijf: ${req.company} (op de muur: ${req.name}). Plaats: ${req.city || "onbekend"}. Domeinen uit de bestelling of de zoektocht: ${asked.map((a) => a.domain).filter(Boolean).join(", ") || "geen"}.`,
  `Hieronder ${shown.length} kandidaat-logo's. Kies het logo dat echt van dit bedrijf is. Let op naamgenoten in andere landen of branches, verouderde logo's en plaatjes die geen logo zijn (foto's, standaardicoontjes, lege favicons). Een woordmerk met de naam heeft de voorkeur boven alleen een symbool. Kies 0 als geen enkel plaatje zeker van dit bedrijf is: liever geen logo dan een verkeerd logo.`,
  "Het logo wordt op de muur als donkere inkt op gebroken wit gedrukt. ink = donker voor een donker logo op een lichte of doorzichtige achtergrond, licht voor een wit of licht logo, kleur alleen als het zonder zijn kleuren niet meer herkenbaar is."
].join("\n\n");
const content = [{ type: "text", text: intro }];
shown.forEach((c, n) => {
  content.push({ type: "text", text: `Kandidaat ${n + 1}: ${c.source}, domein ${c.domain}${c.brand ? `, merknaam "${c.brand}"` : ""}, soort ${c.type}${c.theme ? `, thema ${c.theme}` : ""}.` });
  content.push({ type: "image", source: { type: "url", url: c.viewUrl } });
});

const claudeBody = {
  model: "claude-opus-5-5",
  max_tokens: 1500,
  fallbacks: "default",
  output_config: { effort: "low", format: { type: "json_schema", schema: { "type": "object", "properties": { "choice": { "type": "integer", "description": "Nummer van het kandidaat-logo dat echt van dit bedrijf is; 0 als geen enkel plaatje zeker van dit bedrijf is." }, "confidence": { "type": "number", "description": "Hoe zeker, van 0 tot 1." }, "ink": { "type": "string", "enum": ["donker", "licht", "kleur"], "description": "donker: donker logo op licht of doorzichtig; licht: wit of licht logo; kleur: alleen als het zonder kleur niet herkenbaar is." }, "note": { "type": "string", "description": "Eén zin in het Nederlands voor de beheerder: waarom dit logo, of waarom geen." } }, "required": ["choice", "confidence", "ink", "note"], "additionalProperties": false } } },
  messages: [{ role: "user", content }]
};
return [{ json: { ...req, domains: asked.map((a) => a.domain).filter(Boolean), candidates: shown, claudeBody: shown.length ? claudeBody : null } }];

// Code-node "Keuze": wat Claude koos, als bericht voor het Apps Script (actie wallOfFameLogo).
const cfg = $('Instellingen').first().json;
const req = $('Kandidaten').first().json;
const res = $input.first().json ?? {};
let answer = null;
try {
  const text = res.stop_reason === "refusal" ? "" : (res.content ?? []).find((b) => b.type === "text")?.text;
  answer = text ? JSON.parse(text) : null;
} catch {
  answer = null;
}
const pick = answer && Number.isInteger(answer.choice) && answer.choice >= 1 ? req.candidates[answer.choice - 1] ?? null : null;
const confidence = answer && typeof answer.confidence === "number" ? Math.max(0, Math.min(1, answer.confidence)) : null;
const failure = res.error?.message ? `Claude gaf een fout: ${res.error.message}` : "Geen bruikbaar antwoord van Claude.";
return [
  {
    json: {
      action: "wallOfFameLogo",
      secret: cfg.callbackSecret,
      key: req.key,
      found: Boolean(pick),
      logoUrl: pick ? pick.wallUrl : "",
      ink: ["donker", "licht", "kleur"].includes(answer?.ink) ? answer.ink : "donker",
      source: pick ? pick.source : "n8n",
      // Waar het logo vandaan komt. Is dat niet het domein van de besteller, dan krijgt beheer een waarschuwing.
      logoDomain: pick ? pick.domain : "",
      confidence: pick ? confidence : null,
      note: String(answer?.note ?? failure).slice(0, 400)
    }
  }
];

// Code-node "Niets gevonden": geen enkel logo bij Brandfetch of Logo.dev. Het naambordje blijft hangen.
const cfg = $('Instellingen').first().json;
const req = $input.first().json;
return [
  {
    json: {
      action: "wallOfFameLogo",
      secret: cfg.callbackSecret,
      key: req.key,
      found: false,
      logoUrl: "",
      ink: "donker",
      source: "n8n",
      logoDomain: "",
      confidence: null,
      note: `Geen logo gevonden bij Brandfetch of Logo.dev voor ${req.name}${req.domains.length ? ` (${req.domains.join(", ")})` : ""}; het naambordje blijft hangen.`
    }
  }
];
